mapper.select:
select * from ( SELECT DISTINCT ee.user_id originId, ee.employee_name referrerName, CASE
WHEN ee.work_status = 0 THEN '试用' WHEN ee.work_status = 1 THEN '正式' WHEN ee.work_status = 2 THEN '离职' WHEN ee.work_status = 3 THEN '实习' ELSE '' END workStatus, (select count(1) from base_patient_origin_log where origin_type = 1 AND inservice = 1 and origin_id = ee.user_id ) patientNumber
FROM base_employee ee JOIN base_user_post bup ON bup.user_id = ee.user_id WHERE 1 = 1
and ee.work_status = #{query.workStatus}
and bup.org_id in
#{orgId}
and ee.user_id = #{query.employeeId}
and concat( IFNULL( ee.`employee_name`, '' )) LIKE concat( concat( '%', #{query.referrerName} ), '%' )
ORDER BY patientNumber desc ) t where t.patientNumber > 0

select bill_id,patient_id,actual_amount,orderWorkload from ( SELECT bb.bill_id,
bb.patient_id, bb.actual_amount, ( select TRUNCATE (SUM(((price * quantity) - discount_amount)) / bb.actual_amount,2) from base_bill_detail bbd where bbd.bill_id = bb.bill_id and bbd.executor_id is not null ) as orderWorkload FROM base_bill bb where bb.actual_amount > 0
and bb.bill_id in
#{billId}
GROUP BY bb.bill_id
) t where t.OrderWorkload > 0
